def pasar_las_ventas_de_mostrador(apps, schema_editor):
    """B-06-005: las ventas presenciales ya registradas toman sus valores propios."""
    Pedido = apps.get_model("pedidos", "Pedido")
    LineaPedido = apps.get_model("pedidos", "LineaPedido")
    TransicionDePedido = apps.get_model("pedidos", "TransicionDePedido")
    presenciales = Pedido.objects.filter(canal="presencial")
    LineaPedido.objects.filter(pedido__in=presenciales, estado="despachado").update(
        estado="entregado_en_local"
    )
    TransicionDePedido.objects.filter(pedido__in=presenciales, estado_nuevo="despachado").update(
        estado_nuevo="vendido_en_local"
    )
    presenciales.update(estado="vendido_en_local", modalidad="mostrador")


def volver_a_despachado(apps, schema_editor):
    Pedido = apps.get_model("pedidos", "Pedido")
    LineaPedido = apps.get_model("pedidos", "LineaPedido")
    TransicionDePedido = apps.get_model("pedidos", "TransicionDePedido")
    presenciales = Pedido.objects.filter(canal="presencial")
    LineaPedido.objects.filter(pedido__in=presenciales, estado="entregado_en_local").update(
        estado="despachado"
    )
    TransicionDePedido.objects.filter(
        pedido__in=presenciales, estado_nuevo="vendido_en_local"
    ).update(estado_nuevo="despachado")
    presenciales.update(estado="despachado", modalidad="envio")


